/**
 * `install.sh` on a Mac (issue #7 on nouride-releases, findings 2 and 4, and darwin-arm64 becoming a published target).
 *
 * The LaunchAgent was generated by `nouride service install` with no `--kind`, so a binary that took itself for Linux
 * wrote `nouride.service` and the install stopped at "launchd plist was not written". The data directory was made on
 * Linux only, while the plist sends the daemon's output to `.nouride/data/nouride.log` and launchd makes no directory
 * above a log: the first boot's output, the one-time admin password in it, went nowhere. And macOS is published for
 * Apple Silicon only, so an Intel Mac is told so before anything is downloaded. The blocks are taken from the script as
 * written and run by `sh`, with `nouride` and `launchctl` stood in for.
 */

import { afterEach, describe, expect, test } from "bun:test";
import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const INSTALL = readFileSync(join(import.meta.dir, "../../../../scripts/install.sh"), "utf8");
const between = (from: string, to: string) => INSTALL.slice(INSTALL.indexOf(from) + from.length, INSTALL.indexOf(to));
const GROUP_BLOCK = between("# >>> service group\n", "# <<< service group");
const HOME_BLOCK = between("# >>> home\n", "# <<< home");
const LAUNCHD_BLOCK = between("# >>> launchd agent\n", "  # <<< launchd agent");
const MAC_TARGET = between("# >>> mac target\n", "# <<< mac target");
const DASHBOARD_ADDRESS = between("# >>> dashboard address\n", "# <<< dashboard address");
const me = (flag: "-un" | "-gn") => spawnSync("id", [flag], { encoding: "utf8" }).stdout.trim();

const dirs: string[] = [];
afterEach(() => {
  for (const dir of dirs.splice(0)) rmSync(dir, { recursive: true, force: true });
});
function scratch(): string {
  const dir = mkdtempSync(join(tmpdir(), "nouride-mac-install-"));
  dirs.push(dir);
  return dir;
}

const sh = (script: string, env: Record<string, string> = {}) =>
  spawnSync("sh", ["-c", `set -eu\nsay() { echo "$*"; }\ndie() { echo "$*" >&2; exit 1; }\n${script}`], {
    encoding: "utf8",
    env: { PATH: process.env.PATH ?? "/usr/bin:/bin", ...env },
  });

describe("the home step on a Mac", () => {
  /**
   * The account's own home, stood in for with `getent`: the step carries its dotfiles (`.ssh`, `.config`, `.local`,
   * `.aws`, `.gnupg`…) into the agents' home, and where `getent` is real, as on Linux, it copied the machine's own keys
   * into a temp folder, and failed on a box where one of them was not readable (0.8.17).
   */
  function account(dir: string): Record<string, string> {
    const bin = join(dir, "bin");
    const home = join(dir, "account");
    mkdirSync(bin, { recursive: true });
    mkdirSync(home, { recursive: true });
    writeFileSync(join(home, ".gitconfig"), "[user]\n\tname = the account's\n");
    writeFileSync(join(bin, "getent"), `#!/bin/sh\n[ "$1" = passwd ] && echo '${me("-un")}:x:1000:1000::${home}:/bin/sh'\n`, { mode: 0o755 });
    return { PATH: `${bin}:${process.env.PATH ?? "/usr/bin:/bin"}` };
  }

  test("makes .nouride/data before the LaunchAgent is loaded, so the first boot's log has somewhere to go", () => {
    const dir = scratch();
    const install = join(dir, "install");
    mkdirSync(install);
    const run = sh(`OS=Darwin\nINSTALL_DIR='${install}'\nSERVICE_USER='${me("-un")}'\n${GROUP_BLOCK}\n${HOME_BLOCK}`, account(dir));
    expect(run.stderr).toBe("");
    expect(run.status).toBe(0);
    expect(statSync(join(install, ".nouride", "data")).isDirectory()).toBe(true);
    expect(statSync(join(install, ".nouride", "data")).mode & 0o777).toBe(0o750);
    // What it carried is the stand-in account's, and nothing of the home of whoever runs the test.
    expect(readFileSync(join(install, ".nouride", "home", ".gitconfig"), "utf8")).toBe("[user]\n\tname = the account's\n");
    expect(readdirSync(join(install, ".nouride", "home")).toSorted()).toEqual([".gitconfig", ".ssh"]);
    expect(readdirSync(join(install, ".nouride", "home", ".ssh"))).toEqual([]);
  });

  test("and comes before the LaunchAgent in the script", () => {
    expect(INSTALL.indexOf("# >>> home")).toBeLessThan(INSTALL.indexOf("# >>> launchd agent"));
  });
});

describe("the LaunchAgent", () => {
  /** A `nouride` that writes the plist only when told `--kind launchd`, as a binary built for Linux would not. */
  function standIns(dir: string): { install: string; home: string; calls: string } {
    const install = join(dir, "install");
    const home = join(dir, "home");
    const bin = join(dir, "bin");
    const calls = join(dir, "calls");
    for (const d of [install, home, bin]) mkdirSync(d, { recursive: true });
    writeFileSync(
      join(install, "nouride"),
      `#!/bin/sh\necho "nouride $* HOME=$HOME" >> '${calls}'\ncase " $* " in *" --kind launchd "*) echo plist > '${install}/tech.nouverse.nouride.plist' ;; *) echo unit > '${install}/nouride.service' ;; esac\n`,
      { mode: 0o755 },
    );
    writeFileSync(join(bin, "launchctl"), `#!/bin/sh\necho "launchctl $*" >> '${calls}'\n`, { mode: 0o755 });
    return { install, home, calls };
  }

  test("is generated as a launchd plist by name, with the account's HOME, and loaded", () => {
    const dir = scratch();
    const { install, home, calls } = standIns(dir);
    const run = sh(`INSTALL_DIR='${install}'\nUSER_HOME='${home}'\nSERVICE_USER='${me("-un")}'\nHOME=/var/root\n${LAUNCHD_BLOCK}`, {
      PATH: `${join(dir, "bin")}:${process.env.PATH ?? "/usr/bin:/bin"}`,
    });
    expect(run.stderr).toBe("");
    expect(run.status).toBe(0);
    const log = readFileSync(calls, "utf8");
    expect(log).toContain(`service install --kind launchd --user ${me("-un")} --dir ${install} HOME=${home}`);
    expect(existsSync(join(home, "Library", "LaunchAgents", "tech.nouverse.nouride.plist"))).toBe(true);
    expect(log).toContain(`launchctl load -w ${home}/Library/LaunchAgents/tech.nouverse.nouride.plist`);
  });
});

describe("which Mac has a published build", () => {
  const target = (TARGET: string, TARBALL = "") => sh(`OS=Darwin\nTARGET=${TARGET}\nTARBALL='${TARBALL}'\n${MAC_TARGET}\necho go on`);

  test("Apple Silicon goes on to download", () => {
    expect(target("darwin-arm64").stdout).toContain("go on");
  });

  test("an Intel Mac is told there is none, before anything is downloaded — unless it brings its own tarball", () => {
    const run = target("darwin-x64");
    expect(run.status).toBe(1);
    expect(run.stderr).toContain("Apple Silicon only");
    expect(run.stderr).toContain("--target darwin-x64");
    expect(target("darwin-x64", "/tmp/nouride-darwin-x64.tar.gz").stdout).toContain("go on");
  });
});

describe("where the dashboard is, said at the end", () => {
  const address = (OS: string) => sh(`OS=${OS}\nBIND_HOST=127.0.0.1\nPORT=18254\n${DASHBOARD_ADDRESS}`);

  test("a Mac is told to open it there, not to tunnel to itself", () => {
    const run = address("Darwin");
    expect(run.status).toBe(0);
    const [first, second] = run.stdout.split("\n");
    expect(first).toContain("On this Mac, open  http://127.0.0.1:18254/dashboard/");
    expect(second).toStartWith("From another machine:  ssh -L 18254:127.0.0.1:18254");
  });

  test("a Linux server is still told to tunnel to it from your own machine", () => {
    const run = address("Linux");
    expect(run.status).toBe(0);
    expect(run.stdout).toContain("From your own machine:\n  ssh -L 18254:127.0.0.1:18254");
    expect(run.stdout).not.toContain("On this Mac");
  });
});
